<?php require_once 'includes/functions.php';$u=login_required('patient');$bg=$_GET['blood_group']??'';$loc=trim($_GET['location']??'');$sql="SELECT u.user_id,u.name,u.blood_group,u.location,dp.availability,dp.eligible,dp.last_donation FROM users u JOIN donor_profiles dp ON dp.user_id=u.user_id WHERE u.role='donor' AND dp.availability='Available' AND dp.eligible=1";$a=[];if(in_array($bg,['A+','A-','B+','B-','AB+','AB-','O+','O-'])){$sql.=' AND u.blood_group=?';$a[]=$bg;}if($loc!==''){$sql.=' AND u.location LIKE ?';$a[]='%'.$loc.'%';}$s=db()->prepare($sql);$s->execute($a);$ds=$s->fetchAll();foreach($ds as &$d)$d['score']=score($d,$loc);unset($d);usort($ds,fn($x,$y)=>$y['score']<=>$x['score']);$title='Find donors';require 'includes/header.php';?><h1>Find a donor</h1><form class="filters"><label>Blood group<select name="blood_group"><option value="">Any</option><?php foreach(['A+','A-','B+','B-','AB+','AB-','O+','O-'] as $b):?><option <?= $bg===$b?'selected':''?>><?=e($b)?></option><?php endforeach;?></select></label><label>Location<input name="location" value="<?=e($loc)?>"></label><button class="btn">Search</button></form><section class="cards"><?php foreach($ds as $d):?><article><h3><?=e($d['name'])?> · <?=e($d['blood_group'])?></h3><p><?=e($d['location'])?> · Match score <?= (int)$d['score']?>/100</p><form method="post" action="request.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="donor_id" value="<?=(int)$d['user_id']?>"><label>Hospital / collection point<input name="hospital" required></label><label>Details<textarea name="details"></textarea></label><button class="btn">Send request</button></form></article><?php endforeach;?></section><?php if(!$ds):?><p class="panel">No available matching donors found. Try another location or blood group.</p><?php endif;?><?php require 'includes/footer.php';?>